# Shared helpers for the KeystoneOS run ledger and job registry.
# Dot-source this file; it defines functions and does no work on its own.
#
# The ledger answers one question nothing else could answer: "did this job actually
# succeed today?" Before it existed, the scheduler's own history was the only record,
# and that records "the process exited", not "the work happened".

Set-StrictMode -Version Latest

function Test-ScheduledOn {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date)
    )
    switch ($Job.schedule.kind) {
        'daily'    { return $true }
        'weekdays' { return ($Date.DayOfWeek -ne [DayOfWeek]::Saturday -and $Date.DayOfWeek -ne [DayOfWeek]::Sunday) }
        'weekly'   { return ($Date.DayOfWeek.ToString() -eq $Job.schedule.dayOfWeek) }
        default    { return $false }
    }
}

function Get-ScheduledDateTime {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date)
    )
    $parts = $Job.schedule.at.Split(':')
    $Date.Date.AddHours([int]$parts[0]).AddMinutes([int]$parts[1])
}

function Test-InMakeupWindow {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Now = (Get-Date)
    )
    if (-not $Job.PSObject.Properties['makeupWindow'] -or -not $Job.makeupWindow) { return $true }
    $from = $Job.makeupWindow.from.Split(':')
    $to = $Job.makeupWindow.to.Split(':')
    $start = $Now.Date.AddHours([int]$from[0]).AddMinutes([int]$from[1])
    $end = $Now.Date.AddHours([int]$to[0]).AddMinutes([int]$to[1])
    ($Now -ge $start -and $Now -le $end)
}
